[hidden] { display: none !important; }
:root { color-scheme: dark; --ink: #f4f2e9; --muted: #b7c1d2; --navy: #17233b; --panel: #202f4b; --mint: #a8f0c6; --gold: #ffd477; --line: #3a4a68; }
* { box-sizing: border-box; }
body { margin: 0; min-height: 100vh; padding: 32px 16px; display: grid; place-items: center; background-color: var(--navy); background-image: linear-gradient(135deg, transparent 75%, #22314d 75%), linear-gradient(315deg, transparent 75%, #1b2943 75%); background-size: 40px 40px; color: var(--ink); font: 16px/1.5 system-ui, -apple-system, "Segoe UI", sans-serif; }
.planner { width: min(100%, 760px); padding: clamp(24px, 6vw, 48px); border: 1px solid #435473; border-radius: 24px; background: var(--panel); box-shadow: 0 24px 70px #0b1426a8; }
.header { text-align: center; }
.pixel-mark { display: grid; place-items: center; width: 54px; height: 54px; margin: 0 auto 16px; border: 2px solid var(--mint); border-radius: 14px; color: var(--mint); font-size: 32px; line-height: 1; }
.eyebrow { margin: 0 0 6px; color: var(--mint); font-size: 14px; font-weight: 800; letter-spacing: .14em; }
h1 { margin: 0; font-size: clamp(28px, 6vw, 42px); line-height: 1.15; letter-spacing: -.04em; }
.intro { max-width: 460px; margin: 12px auto 28px; color: var(--muted); }
.fields { display: grid; grid-template-columns: repeat(3, 1fr); gap: 14px; }
label { display: block; color: var(--ink); font-weight: 650; }
.unit { float: right; color: var(--muted); font-weight: 500; }
input { display: block; width: 100%; min-height: 52px; margin-top: 8px; padding: 10px 12px; border: 1px solid #596b89; border-radius: 10px; outline: none; background: #142039; color: var(--ink); font: inherit; font-variant-numeric: tabular-nums; }
input:hover { border-color: var(--mint); }
input:focus-visible, button:focus-visible, .table-wrap:focus-visible { outline: 3px solid var(--gold); outline-offset: 3px; }
button { width: 100%; min-height: 54px; margin-top: 18px; padding: 12px 18px; border: 0; border-radius: 10px; background: var(--mint); color: #142039; font: inherit; font-weight: 800; cursor: pointer; transition: transform .12s ease, background-color .12s ease, box-shadow .12s ease; }
button span { padding-left: 6px; font-size: 20px; }
button:hover { transform: translateY(-2px); background: #c2f8d6; box-shadow: 0 6px 0 #6fbd91; }
button:active { transform: translateY(1px); box-shadow: none; }
.error { margin: 12px 0 0; color: #ffb4a8; }
#results { margin-top: 34px; padding-top: 28px; border-top: 1px solid var(--line); }
#results h2 { margin: 0 0 14px; font-size: 21px; }
.summary { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; margin-bottom: 28px; }
.stat { min-width: 0; padding: 16px; border: 1px solid var(--line); border-radius: 12px; background: #192640; }
.stat-label, .stat-note { display: block; color: var(--muted); font-size: 14px; }
.stat strong { display: block; margin: 4px 0; color: var(--mint); font-size: clamp(20px, 4vw, 28px); font-variant-numeric: tabular-nums; }
.table-heading { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; margin-bottom: 10px; }
.table-heading h2 { margin: 0 !important; }
.table-heading span, .footnote { color: var(--muted); font-size: 14px; }
.table-wrap { overflow-x: auto; border: 1px solid var(--line); border-radius: 10px; }
table { width: 100%; border-collapse: collapse; white-space: nowrap; font-variant-numeric: tabular-nums; }
th, td { padding: 12px 14px; border-bottom: 1px solid var(--line); text-align: right; }
th { color: var(--muted); font-size: 14px; font-weight: 650; }
th:first-child, td:first-child { text-align: left; }
tbody tr:last-child td { border-bottom: 0; }
tbody tr:nth-child(even) { background: #ffffff08; }
td:last-child { color: var(--mint); font-weight: 700; }
.footnote { margin: 12px 0 0; }
footer { margin-top: 28px; color: #8291aa; text-align: center; font-size: 12px; font-weight: 750; letter-spacing: .12em; }
@media (max-width: 560px) { body { padding: 16px 10px; } .planner { padding: 24px 18px; border-radius: 18px; } .fields { grid-template-columns: 1fr; gap: 12px; } .summary { grid-template-columns: 1fr; } .stat { padding: 12px 14px; } .table-heading { align-items: flex-start; flex-direction: column; gap: 2px; } }

const form = document.getElementById('planner-form');
const results = document.getElementById('results');
const error = document.getElementById('error');
const schedule = document.getElementById('schedule');
const money = new Intl.NumberFormat(undefined, { style: 'currency', currency: 'USD' });

function formatMoney(value) {
  return money.format(value);
}

form.addEventListener('submit', (event) => {
  event.preventDefault();
  error.hidden = true;
  const goal = Number(form.elements.goal.value);
  const deposit = Number(form.elements.deposit.value);
  const yearlyRate = Number(form.elements.rate.value);
  const monthlyRate = Math.pow(1 + yearlyRate / 100, 1 / 12) - 1;

  if (!(goal > 0) || !(deposit > 0) || yearlyRate < 0 || yearlyRate > 1000) {
    error.textContent = 'Enter a positive goal and deposit, and a yearly rate from 0 to 1,000%.';
    error.hidden = false;
    results.hidden = true;
    return;
  }

  let balance = 0;
  let totalDeposits = 0;
  let month = 0;
  const rows = [];
  while (balance < goal && month < 1200) {
    month += 1;
    const start = balance;
    const earned = start * monthlyRate;
    balance = start + earned + deposit;
    totalDeposits += deposit;
    rows.push(`<tr><td>${month}</td><td>${formatMoney(start)}</td><td>${formatMoney(earned)}</td><td>${formatMoney(deposit)}</td><td>${formatMoney(balance)}</td></tr>`);
  }

  if (balance < goal) {
    error.textContent = 'This plan does not reach the goal within 100 years. Try a larger monthly deposit.';
    error.hidden = false;
    results.hidden = true;
    return;
  }

  document.getElementById('months').textContent = `${month} ${month === 1 ? 'month' : 'months'}`;
  document.getElementById('duration').textContent = month >= 12 ? `about ${Math.floor(month / 12)} ${Math.floor(month / 12) === 1 ? 'year' : 'years'}${month % 12 ? `, ${month % 12} ${month % 12 === 1 ? 'month' : 'months'}` : ''}` : 'You’ve got this!';
  document.getElementById('interest').textContent = formatMoney(balance - totalDeposits);
  document.getElementById('balance').textContent = formatMoney(balance);
  schedule.innerHTML = rows.join('');
  results.hidden = false;
});
